  "prediction_basis_card_ids": ["C01","C05","C08","C07","C12","C18","C24","C56","C58","C51","C54","C68","C60","C61"],
  "claims": [
    {
      "claim": "Direct human absolute-bioavailability measurements in the most transferable L1 contexts are all above the 20% threshold: imidafenacin 57.8%, tolvaptan 56%, ACT-1004-1239 53%, bromazepam 86%, and lenvatinib ~85%; venadaparib, a benzamide/indazole context structurally closest to the query, is reported as good and 70.63% in mice.",
      "card_ids": ["C01","C05","C08","C07","C12","C18","C24"]
    },
    {
      "claim": "Absorption evidence indicates that low aqueous solubility does not by itself preclude F >= 20%: piroxicam has fa ~100% and negligible first-pass metabolism despite water solubility of only 14.27 µg/mL, and L5 Caco-2 records for heteroaromatic amides/indazoles show high permeability with low efflux.",
      "card_ids": ["C56","C58","C51","C54","C48","C68","C60","C61"]
    },
    {
      "claim": "L6 hepatic-clearance records report in vitro intrinsic clearance values for other molecules (e.g., capmatinib HLM 30.4 µL/min/mg, sorafenib rat microsomes 51.7, compound 3t HLM 110, compound 27 human hepatocytes 12); these are moderate, not scaled to hepatic extraction or in vivo F, and do not affirmatively establish F < 20% for the query.",
      "card_ids": ["C79","C78","C73","C76","C72","C83"]
    },
    {
      "claim": "The affirmative low-F evidence is limited and low-transferability: apatinib L2 10-20% conflicts with its L1 'good' label, ilomastat 'not good' is qualitative and context-specific, and imidafenacin rat 5.6% is species-specific; none affirmatively establishes F < 20% for the query.",
      "card_ids": ["C22","C16","C31"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C72","C73","C74","C75","C76","C77","C78","C79","C80","C81","C82","C83"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental absolute oral bioavailability value for the query molecule.",
    "No query-specific fasted-state solubility, dissolution, permeability, gut-wall efflux, intestinal metabolism, or hepatic clearance data.",
    "L6 records are in vitro CLint measurements for other molecules; scaling to human hepatic extraction and oral F is not provided.",
    "L3 oral AUC/Cmax records lack IV comparators, so they cannot quantify F or confirm the F >= 20% threshold.",
    "Apatinib L2 low value lacks species, dose, formulation, and comparator detail and conflicts with its L1 'good' label.",
    "Most context records are not explicitly fasted; tolvaptan food independence and ARRY-403 fasted data only partially address this."
  ],
  "decision_summary": "Predicted high: F >= 20% remains better supported by multiple transferable direct human absolute-bioavailability contexts (imidafenacin 57.8%, tolvaptan 56%, ACT-1004-1239 53%, bromazepam 86%, lenvatinib ~85%) and by absorption/permeability evidence (piroxicam fa ~100% despite low solubility; high Caco-2 permeability with low efflux). L6 hepatic-clearance records are in vitro, for other molecules, and show only moderate intrinsic clearance values; they do not affirmatively establish F < 20% for the query and do not change the decision. Low-F evidence (apatinib 10-20%, ilomastat 'not good', rat 5.6%) is low-transferability or conflicting. Solubility/lipophilicity and lack of query-specific first-pass data remain uncertainties, not affirmative evidence for low."
}

